head.script:
///////// 1. 변수 및 선언 영역 /////////
///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // 패널라운드 처리
        $c.cm.PanelToGroupBox(panel_1);
        // 파라미터설정
        await scwin.setParam();

        // 목록조회
        /*
        dts_List.SyncLoad = true;
        dts_List.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=BNS_INST_INFO";
        dts_List.Reset();
        dts_List.SyncLoad = false;
         */

        // fn_Search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41095_1.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41095_1.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name txb_SrtyNm_onkeypress
 * @description txb_SrtyNm onkeypress 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_SrtyNm_onkeypress = async function() {
    try {
        if (window.event.keyCode === 13) await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41095_1.txb_SrtyNm_onkeypress" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41095_1.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name grd_List_OnDblClick
 * @description grd_List 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_OnDblClick = async function(row, colid) {
    try {
        if (row > 0) {
            let arrPar = new Array();
            arrPar[0] = {
                SRTY_CD: dts_List.getCellData(row, "SRTY_CD"),
                SRTY_NM: dts_List.getCellData(row, "SRTY_NM")
            };
            fn_SetPar(arrPar);
            await $c.win.closePopup();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41095_1.grd_List_OnDblClick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41095_1.dts_List_OnLoadError" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description 보증인 데이터를 조회한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    url += "&outputMessageId=ETN_SRTY_LIST";
    url += "&SCREN_ID=" + 'ULDSTF41095_1.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&COM_NM=" + txb_SrtyNm.getValue();
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/etn/EtnLstSprt.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setParam
 * @description 부모창에서 받은 데이터를 설정한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParam = async function() {
    const prt = $c.frame.path("../");
    if (prt !== undefined) {
        fn_GetPar = prt.fn_GetPar;
        fn_SetPar = prt.fn_SetPar;
    }
    if (fn_GetPar !== undefined) {
        let arrPar = new Array();
        fn_GetPar(arrPar);
        txb_SrtyNm.setValue(arrPar[0].SRTY_CD);
        await scwin.search();
    }
};
